error_handling.code:
// Result type: Result(Value, Error)
pub fn safe_div(x: Int, y: Int) -> Result(Int, String) {
  case y {
    0 -> Error("DivByZero")
    _ -> Ok(x / y)
  }
}

// Using 'use' for monadic binding (early return)
pub fn div_twice(x, y) {
  use step1 <- gleam/result.try(safe_div(x, y))
  safe_div(step1, y)
}
